(window.__DS = window.__DS || {})["urg"] = {"sections": [{"id": "urg-plantao", "title": "Primeiro plantão: como se situar", "sub": "Organização, triagem, ABCDE e passagem de caso", "blocks": [{"t": "box", "label": "Ainda sem slides", "v": "Este bloco é material de apoio montado a partir de diretrizes e artigos (botões em cada página). Quando os slides da disciplina chegarem, eles viram a base e o que está aqui passa a aparecer como complemento."}, {"t": "h2", "v": "O que se espera do interno na urgência"}, {"t": "ul", "v": ["Chegar antes, saber <b>onde fica</b> o carrinho de parada, o desfibrilador, o material de via aérea, o oxigênio e o aspirador.", "Saber o <b>fluxo do serviço</b>: triagem, sala vermelha (emergência), sala amarela/observação, consultórios, para onde vai o exame e como se pede vaga.", "Ver o paciente <b>sempre pelo ABCDE</b> antes de pensar em diagnóstico.", "Reconhecer quem é <b>grave</b> e chamar ajuda cedo. Chamar o residente ou o plantonista nunca é erro; atrasar é.", "Escrever: anamnese dirigida, exame, hipóteses, conduta e reavaliação, com horário.", "Reavaliar. Na urgência o diagnóstico é um filme, não uma foto: toda conduta tem um \"e depois?\"."]}, {"t": "box", "label": "Regra de ouro", "v": "Tratar primeiro o que mata primeiro. A investigação do porquê vem depois que A, B e C estão garantidos."}, {"t": "escreva", "id": "urg-plantao-w-chegou-no-plantao", "label": "Chegou no plantão", "v": "O que fazer nos primeiros 15 minutos.", "li": ["Achar carrinho de parada, desfibrilador, via aérea, O2 e aspirador", "Entender o fluxo: triagem → sala vermelha / amarela / consultório", "Pegar a passagem dos pacientes da sala vermelha primeiro"]}, {"t": "lance", "q": "Qual a regra de ouro do atendimento de urgência?", "a": "Tratar primeiro o que mata primeiro: garantir A, B e C antes de investigar a causa."}, {"t": "h2", "v": "Triagem: o sistema de Manchester"}, {"t": "p", "v": "A maioria dos prontos-socorros brasileiros usa a classificação de risco de <b>Manchester</b>: a enfermagem escolhe um fluxograma pela queixa e chega a uma cor, que define o tempo máximo até o atendimento médico."}, {"t": "table", "head": ["Cor", "Prioridade", "Tempo-alvo"], "rows": [["Vermelho", "Emergência", "Imediato"], ["Laranja", "Muito urgente", "10 min"], ["Amarelo", "Urgente", "60 min"], ["Verde", "Pouco urgente", "120 min"], ["Azul", "Não urgente", "240 min"]]}, {"t": "ul", "v": ["A cor é dada pelo <b>discriminador mais grave</b> presente (via aérea, choque, dor intensa, alteração de consciência, etc.).", "O paciente pode e deve ser <b>reclassificado</b> se piorar na espera."]}, {"t": "p", "v": "<cx>[Complemento]</cx> Por que importa para o interno: o paciente verde que espera há duas horas pode ter virado laranja. Olhar a sala de espera faz parte do plantão."}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://pubmed.ncbi.nlm.nih.gov/22319249/\" target=\"_blank\" rel=\"noopener\">Thim 2012 · Abordagem ABCDE, Int J Gen Med (PubMed) ↗</a>"}, {"t": "lance", "q": "Qual o tempo-alvo de atendimento da cor laranja no Manchester?", "a": "10 minutos (muito urgente)."}, {"t": "h2", "v": "A abordagem ABCDE do paciente clínico"}, {"t": "p", "v": "É a mesma sequência para qualquer paciente instável. Cada letra é avaliada e <b>tratada</b> antes de passar para a próxima; se algo piora, volta para o A."}, {"t": "table", "head": ["Letra", "Olhar", "Agir já"], "rows": [["A · Via aérea", "Fala? Ruído (estridor, roncos, gargarejo)? Corpo estranho?", "Aspirar, elevar mento, cânula, chamar ajuda para via aérea definitiva"], ["B · Respiração", "FR, SpO2, esforço, ausculta, simetria", "O2 (alvo 92 a 96%; DPOC 88 a 92%), VNI, tratar broncoespasmo, descomprimir pneumotórax"], ["C · Circulação", "FC, PA, enchimento capilar, pele, diurese, ritmo", "Dois acessos calibrosos, cristalino, monitor, ECG, controlar sangramento"], ["D · Neurológico", "Glasgow ou AVDN, pupilas, <b>glicemia capilar</b>, déficit focal", "Corrigir hipoglicemia, proteger via aérea se Glasgow ≤ 8"], ["E · Exposição", "Despir, pele, temperatura, sangramentos ocultos, picadas", "Aquecer, medir temperatura, procurar a causa"]]}, {"t": "ul", "v": ["Monitorização mínima do paciente grave: <b>monitor cardíaco, oxímetro, PA não invasiva, acesso venoso e O2 disponível</b> (o \"MOV\" do plantão).", "<b>Glicemia capilar no D</b> de todo paciente com alteração de consciência: é o exame mais barato e mais esquecido."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://pubmed.ncbi.nlm.nih.gov/22319249/\" target=\"_blank\" rel=\"noopener\">Thim 2012 · ABCDE, Int J Gen Med (PubMed) ↗</a>"}, {"t": "escreva", "id": "urg-plantao-w-abcde", "label": "ABCDE", "v": "Uma linha por letra.", "li": ["A: fala? ruído? → aspirar, posicionar, cânula", "B: FR, SpO2, ausculta → O2, VNI, descompressão", "C: FC, PA, perfusão → 2 acessos, cristalino, ECG", "D: Glasgow, pupilas, <b>glicemia</b>", "E: despir, temperatura, procurar causa"]}, {"t": "lance", "q": "Que exame simples entra no D de todo paciente com alteração de consciência?", "a": "A glicemia capilar."}, {"t": "h2", "v": "Passar o caso: SBAR"}, {"t": "p", "v": "Na hora de chamar o residente ou passar o plantão, uma estrutura curta evita esquecer o essencial. A mais usada é a <b>SBAR</b>."}, {"t": "table", "head": ["Letra", "Conteúdo", "Exemplo"], "rows": [["S · Situação", "Quem é e o que está acontecendo agora", "\"Sr. J., 64 anos, leito 3, com dor torácica há 40 min e PA 88/50.\""], ["B · Background (contexto)", "Antecedentes e o que já foi feito", "\"Hipertenso, diabético; ECG com supra de ST em DII, DIII e aVF; recebeu AAS.\""], ["A · Avaliação", "O que você acha", "\"Penso em IAM inferior com possível acometimento de VD.\""], ["R · Recomendação", "O que você pede", "\"Peço que avalie agora; já acionei a hemodinâmica?\""]]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://pubmed.ncbi.nlm.nih.gov/16617948/\" target=\"_blank\" rel=\"noopener\">Haig 2006 · SBAR, Jt Comm J Qual Patient Saf (PubMed) ↗</a>"}, {"t": "lance", "q": "O que significa cada letra do SBAR?", "a": "Situação, Background (contexto), Avaliação e Recomendação."}, {"t": "h2", "v": "Sinais de alarme: quem não pode esperar"}, {"t": "ul", "v": ["<b>Via aérea</b> ameaçada: estridor, gargarejo, voz abafada, queimadura de face.", "<b>Respiração</b>: FR > 30 ou < 8, SpO2 < 90% em ar ambiente, uso de musculatura acessória, fala entrecortada.", "<b>Circulação</b>: PAS < 90 mmHg, FC > 130 ou < 40, enchimento capilar > 3 s, pele fria e moteada, lactato ≥ 4.", "<b>Neurológico</b>: Glasgow em queda, déficit focal súbito, convulsão que não para, cefaleia \"a pior da vida\".", "<b>Dor torácica</b> com sudorese, dispneia ou síncope; <b>dor abdominal</b> com abdome em tábua ou instabilidade.", "<b>Febre com hipotensão</b> ou alteração mental (sepse até prova em contrário)."]}, {"t": "box", "label": "Escores que ajudam", "v": "NEWS2 e qSOFA servem para <b>alertar</b>, não para descartar. Um qSOFA negativo não tira sepse (a Surviving Sepsis 2021 recomenda não usá-lo sozinho como triagem)."}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1097/CCM.0000000000005337\" target=\"_blank\" rel=\"noopener\">Evans 2021 · Surviving Sepsis Campaign, Crit Care Med (PubMed) ↗</a>"}, {"t": "mcq", "src": "Treino · ABCDE", "stem": "Homem de 58 anos chega sonolento, roncando, com SpO2 de 86% e PA 100/60. Qual é a primeira medida?", "opts": ["Colher gasometria arterial", "Glicemia capilar e tomografia de crânio", "Abrir a via aérea (elevação do mento ou tração da mandíbula), aspirar e ofertar O2", "Dois acessos venosos e 1 L de cristalino"], "ok": 2, "exp": "<b>C é a correta</b>: o ronco num paciente sonolento é obstrução de via aérea pela língua; o A vem antes de tudo e se trata na hora. A (gasometria) e B (glicemia e TC) são parte da investigação e vêm depois de garantir A e B; a glicemia entra no D. D cuida do C, mas a PA está aceitável e a hipóxia por obstrução mata antes. <b>Revisar</b>: ordem do ABCDE e \"avaliar e tratar antes de passar à próxima letra\"."}, {"t": "lance", "q": "O qSOFA negativo descarta sepse?", "a": "Não; serve para alertar, e a Surviving Sepsis 2021 recomenda não usá-lo sozinho como triagem."}]}, {"id": "urg-pcr", "title": "Parada cardiorrespiratória", "sub": "BLS e ACLS pelas diretrizes da AHA de 2025", "blocks": [{"t": "box", "label": "Ainda sem slides", "v": "Material de apoio pelas diretrizes da American Heart Association de 2025 (botões abaixo). Quando os slides chegarem, eles viram a base."}, {"t": "h2", "v": "Reconhecer a parada e começar"}, {"t": "ul", "v": ["Paciente <b>não responde</b> e <b>não respira ou só tem gasping</b>: é PCR. Checar pulso central (carotídeo ou femoral) por <b>no máximo 10 segundos</b>; na dúvida, comece as compressões.", "Gritar por ajuda, pedir o <b>carrinho de parada e o desfibrilador</b>, anotar o horário.", "Compressões de qualidade:<ul class=\"sub\"><li><b>100 a 120 por minuto</b>, profundidade de <b>5 a 6 cm</b>;</li><li><b>retorno total</b> do tórax a cada compressão;</li><li><b>mínimo de pausas</b> (fração de compressão acima de 80%) e troca de quem comprime <b>a cada 2 minutos</b>.</li></ul>", "Sem via aérea avançada: <b>30 compressões : 2 ventilações</b>. Com via aérea avançada: compressões contínuas e <b>1 ventilação a cada 6 segundos</b> (10 por minuto).", "Evitar hiperventilar: ventilação demais aumenta a pressão intratorácica e reduz o retorno venoso."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1161/CIR.0000000000001369\" target=\"_blank\" rel=\"noopener\">Kleinman 2025 · Adult BLS, AHA Circulation (PubMed) ↗</a>"}, {"t": "escreva", "id": "urg-pcr-w-rcp-de-qualidade", "label": "RCP de qualidade", "v": "Os números que não podem faltar.", "li": ["100 a 120/min, 5 a 6 cm, retorno total", "30:2 sem via aérea; com via aérea, 1 ventilação a cada 6 s", "Troca de compressor a cada 2 min; pausas mínimas"]}, {"t": "lance", "q": "Qual a frequência e a profundidade das compressões?", "a": "100 a 120 por minuto, 5 a 6 cm, com retorno total do tórax."}, {"t": "h2", "v": "Os quatro ritmos e os dois caminhos"}, {"t": "table", "head": ["Ritmo", "Chocável?", "O que fazer"], "rows": [["Fibrilação ventricular (FV)", "Sim", "Choque, RCP 2 min, adrenalina após o 2º choque, antiarrítmico após o 3º"], ["Taquicardia ventricular sem pulso (TVSP)", "Sim", "Igual à FV"], ["Atividade elétrica sem pulso (AESP)", "Não", "RCP, <b>adrenalina o quanto antes</b>, procurar a causa (5H e 5T)"], ["Assistolia", "Não", "Igual à AESP; confirmar em mais de uma derivação, ganho e cabos (\"protocolo da linha reta\")"]]}, {"t": "ul", "v": ["<b>Choque</b>: bifásico na carga recomendada pelo fabricante (em geral 120 a 200 J); se não souber, use a carga máxima. Monofásico: 360 J.", "Depois do choque, <b>volte direto para as compressões</b>, sem checar pulso; o ritmo é reavaliado ao fim dos 2 minutos.", "<b>Adrenalina 1 mg IV/IO a cada 3 a 5 minutos</b>.", "<b>Amiodarona 300 mg</b> em bolus (2ª dose 150 mg) <b>ou lidocaína</b> 1 a 1,5 mg/kg (depois 0,5 a 0,75 mg/kg) na FV/TV refratária ao choque."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1161/CIR.0000000000001376\" target=\"_blank\" rel=\"noopener\">Wigginton 2025 · Adult ALS, AHA Circulation (PubMed) ↗</a>"}, {"t": "escreva", "id": "urg-pcr-w-chocavel-nao-chocavel", "label": "Chocável × não chocável", "v": "O algoritmo em quatro linhas.", "li": ["FV/TVSP: choque → RCP 2 min → choque → adrenalina → choque → amiodarona", "AESP/assistolia: RCP + adrenalina já, 5H/5T", "Adrenalina 1 mg a cada 3 a 5 min", "Amiodarona 300 mg, depois 150 mg"]}, {"t": "lance", "q": "Quando entra a adrenalina na FV e na assistolia?", "a": "Na FV, depois do 2º choque; na assistolia/AESP, o quanto antes."}, {"t": "h2", "v": "As causas reversíveis: 5H e 5T"}, {"t": "table", "head": ["H", "T"], "rows": [["<b>H</b>ipovolemia", "<b>T</b>ensão no tórax (pneumotórax hipertensivo)"], ["<b>H</b>ipóxia", "<b>T</b>amponamento cardíaco"], ["<b>H</b>idrogênio (acidose)", "<b>T</b>oxinas"], ["<b>H</b>ipo/hipercalemia", "<b>T</b>rombose pulmonar (TEP)"], ["<b>H</b>ipotermia", "<b>T</b>rombose coronária (IAM)"]]}, {"t": "ul", "v": ["Na AESP, as causas reversíveis são a principal chance de retorno: o ritmo organizado sem pulso costuma ter uma causa mecânica ou metabólica.", "O <b>ultrassom à beira-leito</b> nas pausas de checagem de ritmo ajuda a ver tamponamento, pneumotórax e VD dilatado (TEP), sem prolongar a pausa.", "Capnografia: <b>ETCO2 &lt; 10 mmHg</b> indica compressão ruim ou prognóstico reservado; uma subida brusca (acima de 35 a 40 mmHg) sugere retorno da circulação espontânea."]}, {"t": "lance", "q": "Cite os 5T.", "a": "Tensão no tórax, tamponamento, toxinas, trombose pulmonar e trombose coronária."}, {"t": "h2", "v": "Depois do retorno da circulação (RCE)"}, {"t": "ul", "v": ["ABCDE de novo: via aérea avançada se ainda não tem, <b>SpO2 entre 92 e 98%</b>, ventilar para PaCO2 normal (35 a 45 mmHg).", "Pressão: evitar hipotensão; manter <b>PAM ≥ 65 mmHg</b> (com volume e vasopressor).", "<b>ECG de 12 derivações</b> logo: supra de ST → cateterismo de emergência.", "<b>Controle de temperatura</b>: no paciente que não obedece a comandos, manter temperatura entre 32 e 37,5 °C e evitar febre.", "Glicemia, eletrólitos, gasometria, lactato e procurar a causa da parada.", "Não decidir prognóstico neurológico cedo: a avaliação é multimodal e feita depois de pelo menos 72 horas do retorno da temperatura normal."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1161/CIR.0000000000001375\" target=\"_blank\" rel=\"noopener\">Hirsch 2025 · Post-Cardiac Arrest Care, AHA Circulation (PubMed) ↗</a>"}, {"t": "lance", "q": "Qual a meta de PAM e de SpO2 depois do RCE?", "a": "PAM ≥ 65 mmHg e SpO2 entre 92 e 98%."}, {"t": "h2", "v": "Arritmias com pulso: instável ou estável?"}, {"t": "p", "v": "A primeira pergunta diante de qualquer taqui ou bradiarritmia com pulso é: <b>o paciente está instável por causa dela?</b> Sinais de instabilidade: hipotensão, alteração aguda da consciência, sinais de choque, dor torácica isquêmica, insuficiência cardíaca aguda."}, {"t": "table", "head": ["Situação", "Conduta"], "rows": [["Taquicardia <b>instável</b>", "<b>Cardioversão elétrica sincronizada</b> (sedar se possível): QRS estreito regular 50 a 100 J; fibrilação atrial 200 J; QRS largo regular 100 J; TV polimórfica = desfibrilar (não sincroniza)"], ["QRS estreito regular <b>estável</b>", "Manobra vagal; <b>adenosina 6 mg</b> IV rápida com flush, depois 12 mg"], ["QRS largo <b>estável</b>", "Tratar como TV até prova em contrário; amiodarona 150 mg em 10 min; chamar o cardiologista"], ["Bradicardia <b>instável</b>", "<b>Atropina 1 mg</b> IV a cada 3 a 5 min (máximo 3 mg); se falhar, marcapasso transcutâneo ou dopamina 5 a 20 mcg/kg/min ou adrenalina 2 a 10 mcg/min"]]}, {"t": "atual", "label": "Choque inicial na FA instável", "v": "A diretriz de 2025 passou a indicar choque sincronizado inicial de <b>200 J</b> na fibrilação atrial instável (antes se começava com cargas menores e escalonava).", "src": [["Craig-Brangan 2026 · Resumo das mudanças AHA 2025, Nursing (PubMed)", "https://doi.org/10.1097/NSG.0000000000000396"], ["Wigginton 2025 · Adult ALS, AHA Circulation (PubMed)", "https://doi.org/10.1161/CIR.0000000000001376"]]}, {"t": "box", "label": "Atenção na bradicardia", "v": "BAV de alto grau (Mobitz II, BAVT) costuma não responder à atropina: prepare logo o marcapasso transcutâneo."}, {"t": "mcq", "src": "Treino · ACLS", "stem": "Durante a RCP, o monitor mostra FV. Já foram dados dois choques e uma dose de adrenalina. Após o terceiro choque, qual é a medicação indicada?", "opts": ["Adrenalina 1 mg, porque já se passaram 2 minutos", "Amiodarona 300 mg IV em bolus", "Atropina 1 mg IV", "Bicarbonato de sódio 1 mEq/kg"], "ok": 1, "exp": "<b>B é a correta</b>: FV/TV refratária ao choque (persistente após o 3º choque) pede antiarrítmico, amiodarona 300 mg (ou lidocaína). A está errada porque a adrenalina vai a cada 3 a 5 minutos, ou seja, a cada dois ciclos, e acabou de ser feita no ciclo anterior. C: atropina não tem lugar na PCR desde 2010; é droga de bradicardia com pulso. D: bicarbonato não é rotina, só em hipercalemia, acidose grave prévia ou intoxicação por tricíclicos. <b>Revisar</b>: sequência choque, adrenalina e antiarrítmico no ritmo chocável."}, {"t": "mcq", "src": "Treino · Taquiarritmia", "stem": "Mulher de 45 anos com palpitação, FC 190 bpm, QRS estreito e regular, PA 70/40 e confusa. Conduta?", "opts": ["Adenosina 6 mg IV em bolus", "Manobra vagal", "Cardioversão elétrica sincronizada", "Amiodarona 150 mg IV em 10 minutos"], "ok": 2, "exp": "<b>C é a correta</b>: há instabilidade (hipotensão e alteração de consciência) causada pela taquicardia, e instável = cardioversão sincronizada, 50 a 100 J para QRS estreito regular. A e B são as condutas da taquicardia supraventricular <b>estável</b>; no instável só se tentam se não atrasarem o choque. D é mais lenta e reservada para QRS largo estável ou controle de FA. <b>Revisar</b>: a pergunta \"estável ou instável?\" vem antes do ritmo."}, {"t": "lance", "q": "Qual a dose de atropina na bradicardia instável?", "a": "1 mg IV a cada 3 a 5 min, máximo de 3 mg."}]}, {"id": "urg-sca", "title": "Dor torácica e síndrome coronariana aguda", "sub": "Pela diretriz ACC/AHA de 2025 para SCA", "blocks": [{"t": "box", "label": "Ainda sem slides", "v": "Material de apoio pela diretriz ACC/AHA/ACEP de 2025 para síndromes coronarianas agudas. Quando os slides chegarem, eles viram a base."}, {"t": "h2", "v": "Dor torácica: os 10 primeiros minutos"}, {"t": "ul", "v": ["<b>ECG de 12 derivações em até 10 minutos</b> da chegada de todo paciente com dor torácica. Se o primeiro não mostra nada e a dor continua, <b>repetir</b> (a cada 15 a 30 min).", "Monitor, acesso venoso, oxímetro; O2 <b>só se SpO2 &lt; 90%</b>.", "As seis causas de dor torácica que matam e não podem passar: <b>SCA, dissecção de aorta, TEP, pneumotórax hipertensivo, tamponamento e ruptura de esôfago</b>.", "Pistas de dissecção antes de anticoagular: dor <b>rasgando</b> que irradia para o dorso, diferença de pulso ou de PA entre os braços, mediastino alargado, sopro de insuficiência aórtica."]}, {"t": "escreva", "id": "urg-sca-w-dor-toracica", "label": "Dor torácica", "v": "O que fazer primeiro.", "li": ["ECG em 10 min, repetir se a dor persiste", "Monitor, acesso, O2 só se SpO2 &lt; 90%", "Pensar nas 6 que matam: SCA, dissecção, TEP, pneumotórax, tamponamento, esôfago"]}, {"t": "lance", "q": "Em quanto tempo o ECG deve ser feito na dor torácica?", "a": "Em até 10 minutos da chegada."}, {"t": "h2", "v": "Ler o ECG: IAM com supra (IAMCSST)"}, {"t": "ul", "v": ["Critério: <b>supradesnivelamento do ST</b> no ponto J em <b>duas derivações contíguas</b>:<ul class=\"sub\"><li>≥ 1 mm em todas as derivações, exceto V2 e V3;</li><li>em V2 e V3: ≥ 2 mm em homens ≥ 40 anos, ≥ 2,5 mm em homens &lt; 40 anos, ≥ 1,5 mm em mulheres.</li></ul>", "Equivalentes que também levam à reperfusão: <b>infradesnível de V1 a V3</b> (IAM posterior; fazer V7 a V9), <b>BRE novo ou presumidamente novo com clínica</b> (critérios de Sgarbossa), supra em aVR com infra difuso (lesão de tronco ou multiarterial, discutir com a hemodinâmica)."]}, {"t": "table", "head": ["Parede", "Derivações", "Artéria provável"], "rows": [["Inferior", "DII, DIII, aVF", "Coronária direita (ou circunflexa)"], ["Anterior", "V1 a V4", "Descendente anterior"], ["Lateral", "DI, aVL, V5, V6", "Circunflexa ou diagonal"], ["Ventrículo direito", "V3R, V4R", "Coronária direita proximal"]]}, {"t": "box", "label": "IAM inferior? Faça V3R e V4R", "v": "Supra em V4R = infarto de VD. Esse paciente depende de pré-carga: <b>nada de nitrato nem morfina</b>; se hipotenso, volume."}, {"t": "lance", "q": "Que derivações fazer num IAM inferior e por quê?", "a": "V3R e V4R, para procurar infarto de VD."}, {"t": "h2", "v": "Tratamento inicial da SCA"}, {"t": "table", "head": ["Medicação", "Dose de ataque", "Observação"], "rows": [["AAS", "162 a 325 mg mastigado (no Brasil, em geral 200 a 300 mg)", "Para todos, salvo alergia verdadeira"], ["Inibidor de P2Y12", "Ticagrelor 180 mg, ou prasugrel 60 mg (só com anatomia conhecida e sem AVC prévio), ou clopidogrel 300 a 600 mg", "Ticagrelor ou prasugrel preferidos na angioplastia; clopidogrel com trombolítico (75 mg se &gt; 75 anos)"], ["Anticoagulante", "Heparina não fracionada ou enoxaparina 1 mg/kg SC 12/12 h", "Ajustar enoxaparina por idade e função renal"], ["Nitrato", "Sublingual se dor e PA preservada", "Contraindicado: PAS &lt; 90, IAM de VD, inibidor de PDE-5 recente"], ["Estatina de alta potência", "Atorvastatina 40 a 80 mg", "Iniciar cedo"]]}, {"t": "ul", "v": ["Betabloqueador oral nas primeiras 24 h se não houver insuficiência cardíaca, baixo débito ou risco de choque.", "Morfina só para dor refratária."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1161/CIR.0000000000001309\" target=\"_blank\" rel=\"noopener\">Rao 2025 · Diretriz ACC/AHA de SCA, Circulation (PubMed) ↗</a>"}, {"t": "atual", "label": "O que mudou em 2025", "v": "A diretriz uniu IAM com e sem supra num só documento: ticagrelor ou prasugrel preferidos ao clopidogrel na angioplastia, bivalirudina com infusão em dose alta na angioplastia primária e meta de LDL com terapia não estatina se o LDL seguir acima de 70 mg/dL.", "src": [["Restrepo 2026 · Controvérsias da diretriz de SCA 2025, Curr Cardiol Rep (PubMed)", "https://doi.org/10.1007/s11886-026-02427-8"]]}, {"t": "lance", "q": "Qual a dose de ataque do ticagrelor?", "a": "180 mg."}, {"t": "h2", "v": "Reperfusão: o relógio do IAM com supra"}, {"t": "ul", "v": ["<b>Angioplastia primária</b> é a escolha se a porta-balão for <b>≤ 90 min</b> (ou ≤ 120 min contando a transferência).", "Sem hemodinâmica nesse tempo: <b>trombolítico em até 30 min da chegada</b> (porta-agulha), se sintomas há menos de 12 h e sem contraindicação. Depois, transferir para angiografia em 2 a 24 h (estratégia fármaco-invasiva), ou na hora se a trombólise falhar (resgate).", "Sinais de reperfusão: alívio da dor, <b>queda do supra ≥ 50%</b> em 60 a 90 min, arritmia de reperfusão (ritmo idioventricular acelerado)."]}, {"t": "table", "head": ["Contraindicações absolutas à trombólise", ""], "rows": [["AVC hemorrágico em qualquer época", "AVC isquêmico nos últimos 3 meses"], ["Neoplasia ou malformação vascular intracraniana", "Suspeita de dissecção de aorta"], ["Sangramento ativo (exceto menstruação)", "TCE ou cirurgia de crânio/coluna nos últimos 3 meses"]]}, {"t": "escreva", "id": "urg-sca-w-tempos-do-iam-com-supra", "label": "Tempos do IAM com supra", "v": "Os números do relógio.", "li": ["ECG em 10 min", "Porta-balão ≤ 90 min (≤ 120 com transferência)", "Porta-agulha ≤ 30 min se não houver angioplastia a tempo"]}, {"t": "lance", "q": "Qual o tempo porta-agulha da trombólise?", "a": "Até 30 minutos."}, {"t": "h2", "v": "Sem supra: troponina e risco"}, {"t": "ul", "v": ["IAM sem supra e angina instável: dor típica sem critério de supra. A <b>troponina de alta sensibilidade</b> separa os dois (sobe no IAM).", "Algoritmos rápidos: troponina na chegada e em <b>1 ou 2 horas</b> (0/1 h ou 0/2 h), conforme o ensaio do hospital.", "Estratificação: HEART (dor torácica indiferenciada) e GRACE (SCA confirmada) guiam a decisão.", "Estratégia invasiva <b>imediata (&lt; 2 h)</b> se: instabilidade hemodinâmica, dor refratária, arritmia grave, insuficiência cardíaca aguda ou complicação mecânica. Precoce (&lt; 24 h) se alto risco (GRACE &gt; 140, alteração dinâmica do ST)."]}, {"t": "mcq", "src": "Treino · SCA", "stem": "Homem de 62 anos com dor precordial há 2 h. ECG: supra de ST de 2 mm em DII, DIII e aVF, com supra de 1 mm em V4R. PA 96/60. Qual conduta deve ser evitada?", "opts": ["AAS 300 mg mastigado", "Nitrato sublingual", "Acionar a hemodinâmica para angioplastia primária", "Cristaloide em alíquotas se a PA cair"], "ok": 1, "exp": "<b>B é a correta (deve ser evitada)</b>: supra em V4R num IAM inferior indica infarto de VD, que depende de pré-carga; nitrato (e morfina) causam vasodilatação venosa e podem levar a hipotensão grave. A é indicada para todos. C é a reperfusão de escolha. D é o tratamento da hipotensão no IAM de VD. <b>Revisar</b>: IAM inferior → sempre V3R e V4R."}, {"t": "lance", "q": "Quando a estratégia invasiva é imediata (&lt; 2 h) no IAM sem supra?", "a": "Instabilidade hemodinâmica, dor refratária, arritmia grave, IC aguda ou complicação mecânica."}]}, {"id": "urg-neuro", "title": "AVC e crise convulsiva", "sub": "Diretriz AHA/ASA 2026 de AVC isquêmico, 2022 de hemorragia e estado de mal epiléptico", "blocks": [{"t": "box", "label": "Ainda sem slides", "v": "Material de apoio pelas diretrizes da AHA/ASA e da American Epilepsy Society (botões abaixo). Quando os slides chegarem, eles viram a base."}, {"t": "h2", "v": "Suspeita de AVC: tempo é cérebro"}, {"t": "ul", "v": ["Déficit neurológico <b>súbito</b>: fraqueza ou dormência de um lado, desvio de rima, fala enrolada ou afasia, perda visual, ataxia. Escala pré-hospitalar simples: <b>SAMU</b> (Sorriso, Abraço, Música, Urgência) ou FAST.", "A pergunta mais importante: <b>a que horas o paciente foi visto bem pela última vez?</b> Acordou com o déficit = conta a hora em que foi dormir.", "Na chegada: ABCDE, <b>glicemia capilar</b> (hipoglicemia imita AVC), NIHSS, e <b>tomografia de crânio sem contraste</b> o mais rápido possível (meta porta-imagem ≤ 20 a 25 min; porta-agulha ≤ 60 min).", "Angiotomografia de crânio e cervical se houver chance de trombectomia (NIHSS alto, afasia, desvio do olhar, negligência)."]}, {"t": "escreva", "id": "urg-neuro-w-chegou-com-deficit-subito", "label": "Chegou com déficit súbito", "v": "Primeiras ações.", "li": ["Horário em que foi visto bem pela última vez", "Glicemia capilar, NIHSS", "TC de crânio sem contraste já; angio-TC se suspeita de oclusão de grande vaso"]}, {"t": "lance", "q": "Qual a pergunta mais importante na suspeita de AVC?", "a": "A que horas o paciente foi visto bem pela última vez."}, {"t": "h2", "v": "Isquêmico: trombólise e trombectomia"}, {"t": "ul", "v": ["<b>Trombólise IV</b> até <b>4,5 h</b> do último momento visto bem, com TC sem sangramento e sem contraindicação:<ul class=\"sub\"><li><b>Alteplase 0,9 mg/kg</b> (máx. 90 mg): 10% em bolus em 1 min e o resto em 60 min; ou</li><li><b>Tenecteplase 0,25 mg/kg</b> (máx. 25 mg) em bolus único.</li></ul>", "PA antes de trombolisar: <b>&lt; 185/110 mmHg</b>; depois, manter <b>&lt; 180/105</b> por 24 h (labetalol, nicardipino ou, no Brasil, nitroprussiato).", "<b>Sem trombólise</b>: tolerar PA até <b>220/120</b> (hipertensão permissiva protege a penumbra).", "<b>Trombectomia mecânica</b> na oclusão de grande vaso da circulação anterior até 6 h, e em pacientes selecionados por imagem até 24 h.", "AAS 160 a 300 mg em 24 a 48 h (se trombolisado, só depois da TC de controle em 24 h). Glicemia entre 140 e 180 mg/dL, cabeceira e avaliação de deglutição antes de dar algo pela boca."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1161/STR.0000000000000513\" target=\"_blank\" rel=\"noopener\">Prabhakaran 2026 · Diretriz AHA/ASA de AVC isquêmico, Stroke (PubMed) ↗</a>"}, {"t": "atual", "label": "Diretriz de 2026", "v": "A diretriz de 2026 substituiu a de 2018/2019. Entre as mudanças: escolha do trombolítico (a tenecteplase entrou como opção), critérios de elegibilidade para trombectomia e uma abordagem revista das contraindicações à trombólise. Confira o protocolo do hospital, que pode usar só alteplase.", "src": [["Prabhakaran 2026 · Stroke (PubMed)", "https://doi.org/10.1161/STR.0000000000000513"], ["Powers 2019 · Diretriz anterior, Stroke (PubMed)", "https://doi.org/10.1161/STR.0000000000000211"]]}, {"t": "escreva", "id": "urg-neuro-w-trombolise", "label": "Trombólise", "v": "Os números do AVC isquêmico.", "li": ["Até 4,5 h; alteplase 0,9 mg/kg (máx. 90), 10% em bolus", "PA &lt; 185/110 antes e &lt; 180/105 por 24 h depois", "Sem trombólise: tolerar até 220/120"]}, {"t": "lance", "q": "Qual a dose da alteplase no AVC?", "a": "0,9 mg/kg (máx. 90 mg), 10% em bolus e o resto em 60 min."}, {"t": "h2", "v": "Hemorrágico: baixar a pressão e reverter"}, {"t": "ul", "v": ["Na TC, sangue = <b>hemorragia intraparenquimatosa</b> (ou subaracnóidea: cefaleia súbita \"a pior da vida\").", "PA: na hemorragia leve a moderada com PAS entre 150 e 220, <b>alvo de PAS de 140 mmHg</b> é razoável; evitar quedas maiores que 70 mmHg e PAS abaixo de 130.", "<b>Reverter anticoagulação já</b>: varfarina → vitamina K IV + complexo protrombínico; dabigatrana → idarucizumabe; inibidores do fator Xa → andexanete (ou complexo protrombínico se não houver).", "Cabeceira a 30°, glicemia e temperatura normais, avaliação neurocirúrgica (hematoma cerebelar com compressão de tronco ou hidrocefalia)."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1161/STR.0000000000000407\" target=\"_blank\" rel=\"noopener\">Greenberg 2022 · Diretriz AHA/ASA de hemorragia intracerebral, Stroke (PubMed) ↗</a>"}, {"t": "lance", "q": "Como reverter a varfarina numa hemorragia intracerebral?", "a": "Vitamina K IV e complexo protrombínico."}, {"t": "h2", "v": "Crise convulsiva e estado de mal epiléptico"}, {"t": "p", "v": "<b>Estado de mal</b>: crise que dura <b>mais de 5 minutos</b> ou crises repetidas sem recuperação da consciência entre elas. O tratamento é por tempo, como um relógio."}, {"t": "table", "head": ["Tempo", "Fase", "Conduta"], "rows": [["0 a 5 min", "Estabilização", "ABCDE, decúbito lateral, O2, monitor, acesso, <b>glicemia capilar</b> (tiamina 100 mg IV antes da glicose se etilista ou desnutrido)"], ["5 a 20 min", "1ª linha: benzodiazepínico", "<b>Midazolam 10 mg IM</b> (&gt; 40 kg), ou lorazepam 0,1 mg/kg IV (máx. 4 mg), ou diazepam 0,15 a 0,2 mg/kg IV (máx. 10 mg); pode repetir uma vez"], ["20 a 40 min", "2ª linha", "<b>Fosfenitoína</b> 20 mg EF/kg, ou <b>ácido valproico</b> 40 mg/kg (máx. 3 g), ou <b>levetiracetam</b> 60 mg/kg (máx. 4,5 g). No Brasil, muito usada: fenitoína 20 mg/kg a até 50 mg/min, com monitor"], ["&gt; 40 min", "Refratário", "IOT e anestésico contínuo (midazolam, propofol), EEG, UTI"]]}, {"t": "ul", "v": ["No ESETT, levetiracetam, fosfenitoína e valproato tiveram <b>eficácia semelhante</b> (cerca de metade dos pacientes parou de convulsionar), então vale o que estiver disponível e for seguro para o paciente.", "Não esquecer a causa: hipoglicemia, hiponatremia, abstinência alcoólica, infecção do SNC, AVC, intoxicação, eclâmpsia (gestante → <b>sulfato de magnésio</b>)."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.5698/1535-7597-16.1.48\" target=\"_blank\" rel=\"noopener\">Glauser 2016 · Diretriz AES de estado de mal, Epilepsy Curr (PubMed) ↗</a>"}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1056/NEJMoa1905795\" target=\"_blank\" rel=\"noopener\">Kapur 2019 · ESETT, N Engl J Med (PubMed) ↗</a>"}, {"t": "escreva", "id": "urg-neuro-w-estado-de-mal", "label": "Estado de mal", "v": "O relógio.", "li": ["&gt; 5 min = estado de mal", "5 min: benzodiazepínico (midazolam 10 mg IM)", "20 min: fenitoína/fosfenitoína, valproato ou levetiracetam", "40 min: IOT + anestésico contínuo"]}, {"t": "mcq", "src": "Treino · AVC", "stem": "Mulher de 70 anos com hemiparesia direita e afasia iniciadas há 2 h. TC sem sangramento, glicemia 132, PA 200/110. Antes da alteplase, o que fazer?", "opts": ["Trombolisar já; a PA será tratada depois", "Baixar a PA para menos de 185/110 e então trombolisar", "Não trombolisar, porque a PA está acima de 220/120", "Aguardar a ressonância para confirmar o infarto"], "ok": 1, "exp": "<b>B é a correta</b>: a trombólise exige PA &lt; 185/110 antes da infusão; com PA controlada, ela é elegível (até 4,5 h). A aumenta o risco de transformação hemorrágica. C confunde: 220/120 é o limite para tolerar a PA de quem <b>não</b> vai trombolisar. D atrasa o tratamento; a TC sem sangramento basta. <b>Revisar</b>: os dois limites de PA no AVC isquêmico."}, {"t": "lance", "q": "A partir de quantos minutos uma crise é estado de mal?", "a": "Mais de 5 minutos (ou crises repetidas sem recuperação)."}]}, {"id": "urg-sepse", "title": "Sepse, choque e anafilaxia", "sub": "Surviving Sepsis Campaign 2021, Sepsis-3 e WAO 2020", "blocks": [{"t": "box", "label": "Ainda sem slides", "v": "Material de apoio pela Surviving Sepsis Campaign 2021 e pela orientação de anafilaxia da World Allergy Organization (botões abaixo). Quando os slides chegarem, eles viram a base."}, {"t": "h2", "v": "Sepse: definição que se usa hoje"}, {"t": "ul", "v": ["<b>Sepse</b> (Sepsis-3): disfunção orgânica com risco de vida causada por resposta desregulada à infecção; na prática, infecção suspeita + aumento de <b>≥ 2 pontos no SOFA</b>.", "<b>Choque séptico</b>: sepse que precisa de <b>vasopressor para PAM ≥ 65 mmHg</b> e tem <b>lactato &gt; 2 mmol/L</b> apesar de volume adequado.", "qSOFA (FR ≥ 22, alteração mental, PAS ≤ 100) alerta, mas não serve sozinho para triagem.", "Disfunções para procurar: hipotensão, rebaixamento, oligúria, creatinina subindo, plaquetas caindo, bilirrubina, hipoxemia, lactato."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1001/jama.2016.0287\" target=\"_blank\" rel=\"noopener\">Singer 2016 · Sepsis-3, JAMA (PubMed) ↗</a>"}, {"t": "lance", "q": "O que define choque séptico pela Sepsis-3?", "a": "Vasopressor para PAM ≥ 65 mmHg e lactato &gt; 2 mmol/L apesar de volume."}, {"t": "h2", "v": "O pacote da primeira hora"}, {"t": "ul", "v": ["<b>Lactato</b> (e repetir em 2 a 4 h se &gt; 2).", "<b>Hemoculturas</b> (2 pares) antes do antibiótico, sem atrasá-lo.", "<b>Antibiótico de amplo espectro</b>: em até <b>1 hora</b> se choque ou sepse provável; se a sepse é só possível e não há choque, investigar rápido e decidir em até 3 h.", "<b>Cristaloide 30 mL/kg nas primeiras 3 h</b> se hipotensão ou lactato ≥ 4 (preferir balanceado, como Ringer lactato), reavaliando a resposta a cada alíquota.", "<b>Noradrenalina</b> se a PAM continuar &lt; 65 mmHg durante ou depois do volume; pode começar em <b>veia periférica</b> calibrosa enquanto se passa o acesso central.", "Choque refratário: associar <b>vasopressina</b> quando a noradrenalina chega a 0,25 a 0,5 mcg/kg/min; <b>hidrocortisona 200 mg/dia</b> se a noradrenalina ≥ 0,25 mcg/kg/min por ≥ 4 h.", "Controle do foco (drenar abscesso, desobstruir via urinária ou biliar, retirar cateter infectado) assim que possível."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1097/CCM.0000000000005337\" target=\"_blank\" rel=\"noopener\">Evans 2021 · Surviving Sepsis Campaign, Crit Care Med (PubMed) ↗</a>"}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1056/NEJMoa1711584\" target=\"_blank\" rel=\"noopener\">Semler 2018 · SMART, balanceado × salina, N Engl J Med (PubMed) ↗</a>"}, {"t": "escreva", "id": "urg-sepse-w-primeira-hora-da-sepse", "label": "Primeira hora da sepse", "v": "O pacote.", "li": ["Lactato; hemoculturas antes do antibiótico", "Antibiótico em 1 h (choque ou sepse provável)", "30 mL/kg de cristaloide se hipotensão ou lactato ≥ 4", "Noradrenalina para PAM ≥ 65"]}, {"t": "lance", "q": "Quanto de cristaloide se dá na sepse com hipotensão?", "a": "30 mL/kg nas primeiras 3 horas, reavaliando."}, {"t": "h2", "v": "Os quatro tipos de choque"}, {"t": "p", "v": "Choque é <b>oferta de oxigênio menor que a demanda</b> dos tecidos. A classificação pelo mecanismo orienta o tratamento."}, {"t": "table", "head": ["Tipo", "Exemplo", "Pele", "Pressões de enchimento (PVC)", "Débito", "Resistência vascular", "Tratar"], "rows": [["Hipovolêmico", "Hemorragia, diarreia", "Fria", "Baixa", "Baixo", "Alta", "Volume ou sangue, parar a perda"], ["Cardiogênico", "IAM extenso", "Fria", "Alta", "Baixo", "Alta", "Inotrópico, reperfusão; cuidado com volume"], ["Obstrutivo", "TEP, tamponamento, pneumotórax hipertensivo", "Fria", "Alta", "Baixo", "Alta", "Desobstruir: trombólise, pericardiocentese, punção"], ["Distributivo", "Sepse, anafilaxia, neurogênico", "Quente (no início)", "Baixa ou normal", "Normal ou alto", "Baixa", "Volume + vasopressor; adrenalina na anafilaxia"]]}, {"t": "ul", "v": ["Sinais de má perfusão para seguir à beira-leito: <b>enchimento capilar &gt; 3 s</b>, pele moteada, oligúria (&lt; 0,5 mL/kg/h), confusão, lactato alto.", "O <b>ultrassom à beira-leito</b> (protocolo RUSH: bomba, tanque e canos) diferencia os tipos em minutos: VD dilatado, derrame pericárdico, VCI, líquido livre, aorta."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1056/NEJMra1208943\" target=\"_blank\" rel=\"noopener\">Vincent 2013 · Choque circulatório, N Engl J Med (PubMed) ↗</a>"}, {"t": "lance", "q": "Quais choques têm pele quente e resistência vascular baixa?", "a": "Os distributivos (sepse, anafilaxia, neurogênico)."}, {"t": "h2", "v": "Anafilaxia: adrenalina intramuscular primeiro"}, {"t": "ul", "v": ["Suspeita: início agudo (minutos a horas) após exposição, com <b>pele/mucosa</b> (urticária, angioedema) + comprometimento <b>respiratório ou circulatório</b>; ou hipotensão/broncoespasmo após alérgeno conhecido, mesmo sem pele.", "<b>Adrenalina IM 0,01 mg/kg</b> da solução 1 mg/mL (máx. <b>0,5 mg</b> no adulto, 0,3 mg na criança) na face anterolateral da coxa; repetir a cada 5 a 15 min se preciso.", "Deitar com as pernas elevadas (gestante em decúbito lateral esquerdo), O2, acesso e <b>cristaloide 1 a 2 L</b> rápido se hipotensão.", "Anti-histamínico e corticoide são <b>adjuvantes</b>: não substituem nem atrasam a adrenalina.", "Refratária a duas ou três doses IM: adrenalina em infusão contínua; em usuário de betabloqueador, considerar <b>glucagon</b>.", "Observar após a melhora (reação bifásica) e dar alta com orientação e plano de adrenalina autoinjetável quando disponível."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1016/j.waojou.2020.100472\" target=\"_blank\" rel=\"noopener\">Cardona 2020 · WAO Anaphylaxis Guidance, World Allergy Organ J (PubMed) ↗</a>"}, {"t": "escreva", "id": "urg-sepse-w-anafilaxia", "label": "Anafilaxia", "v": "O que salva.", "li": ["Adrenalina IM 0,01 mg/kg (máx. 0,5 mg), coxa, repetir em 5 a 15 min", "Deitar com pernas elevadas, O2, volume", "Anti-histamínico e corticoide só depois"]}, {"t": "mcq", "src": "Treino · Sepse", "stem": "Idosa com pneumonia, PA 80/45, FC 118, lactato 5,1 mmol/L. Após 30 mL/kg de Ringer lactato, PAM 58 mmHg. Próximo passo?", "opts": ["Mais 30 mL/kg de cristaloide antes de qualquer droga", "Dobutamina em acesso periférico", "Noradrenalina, mesmo em veia periférica, para PAM ≥ 65", "Hidrocortisona 200 mg/dia e aguardar"], "ok": 2, "exp": "<b>C é a correta</b>: hipotensão persistente após volume = choque séptico; o vasopressor de primeira linha é a noradrenalina, que pode começar em acesso periférico calibroso para não atrasar. A arrisca sobrecarga sem reavaliar; volume extra só se houver sinal de resposta. B: dobutamina é inotrópico, para disfunção miocárdica com baixo débito, não o primeiro passo. D: o corticoide entra se a noradrenalina ficar ≥ 0,25 mcg/kg/min por 4 h. <b>Revisar</b>: definição de choque séptico e escolha do vasopressor."}, {"t": "mcq", "src": "Treino · Anafilaxia", "stem": "Logo após receber ceftriaxona, paciente tem urticária difusa, sibilos e PA 78/40. Qual a medicação de primeira linha?", "opts": ["Prometazina 50 mg IV", "Hidrocortisona 500 mg IV", "Adrenalina 0,5 mg IM na coxa", "Adrenalina 1 mg IV em bolus"], "ok": 2, "exp": "<b>C é a correta</b>: anafilaxia trata-se com adrenalina IM, 0,01 mg/kg até 0,5 mg no adulto, na face anterolateral da coxa. A e B são adjuvantes, sem efeito sobre a hipotensão e o broncoespasmo nos primeiros minutos. D: 1 mg IV em bolus é dose de PCR e, com pulso, pode causar arritmia grave e isquemia; adrenalina IV só em infusão titulada, por quem tem experiência. <b>Revisar</b>: via, dose e local da adrenalina."}, {"t": "lance", "q": "Qual a dose máxima de adrenalina IM no adulto?", "a": "0,5 mg (0,01 mg/kg da solução 1 mg/mL)."}]}, {"id": "urg-via-aerea", "title": "Insuficiência respiratória e intubação", "sub": "Oxigênio, VNI e sequência rápida de intubação", "blocks": [{"t": "box", "label": "Ainda sem slides", "v": "Material de apoio por ensaios clínicos e revisões (botões abaixo). Quando os slides chegarem, eles viram a base."}, {"t": "h2", "v": "Oxigênio: nem de menos nem de mais"}, {"t": "ul", "v": ["Alvo de <b>SpO2 entre 92 e 96%</b> na maioria dos pacientes agudos; <b>88 a 92%</b> em quem retém CO2 (DPOC, obesidade-hipoventilação, doença neuromuscular).", "Hiperóxia também faz mal: a metanálise IOTA mostrou <b>mais mortalidade</b> com oxigênio liberal em adultos agudamente doentes.", "Dispositivos e o que oferecem (aproximado):"]}, {"t": "table", "head": ["Dispositivo", "Fluxo", "FiO2 aproximada"], "rows": [["Cateter nasal", "1 a 5 L/min", "24 a 40% (sobe ~4% por litro)"], ["Máscara simples", "5 a 10 L/min", "35 a 50%"], ["Máscara de Venturi", "Conforme a válvula", "24 a 60%, precisa (boa no DPOC)"], ["Máscara com reservatório", "10 a 15 L/min", "60 a 90%"], ["Cateter nasal de alto fluxo", "Até 60 L/min", "Até 100%, aquecido e umidificado"]]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1016/S0140-6736(18)30479-3\" target=\"_blank\" rel=\"noopener\">Chu 2018 · IOTA, Lancet (PubMed) ↗</a>"}, {"t": "lance", "q": "Qual o alvo de SpO2 no paciente com DPOC retentor?", "a": "88 a 92%."}, {"t": "h2", "v": "Ventilação não invasiva (VNI)"}, {"t": "ul", "v": ["Onde funciona melhor: <b>DPOC exacerbada com acidose respiratória</b> (pH 7,25 a 7,35 e PaCO2 &gt; 45) e <b>edema agudo de pulmão cardiogênico</b>.", "Ajuste inicial de BiPAP: IPAP 10 a 12 cmH2O e EPAP 5 cmH2O, subindo a IPAP conforme o volume e o CO2. No edema agudo, CPAP 5 a 10 cmH2O também serve.", "<b>Contraindicações</b>: parada ou necessidade de intubação imediata, rebaixamento sem proteção de via aérea, vômitos ou sangramento digestivo alto, instabilidade hemodinâmica grave, trauma de face, não colaboração.", "Reavaliar em <b>1 a 2 horas</b> com gasometria: se não melhorou, não insistir; intubar."]}, {"t": "box", "label": "Não atrase a intubação", "v": "VNI que falha e é mantida por horas aumenta a mortalidade. Defina antes o critério de falha."}, {"t": "lance", "q": "Em quais duas situações a VNI tem melhor evidência?", "a": "DPOC exacerbada com acidose respiratória e edema agudo de pulmão cardiogênico."}, {"t": "h2", "v": "Quando intubar"}, {"t": "ul", "v": ["Quatro perguntas:<ul class=\"sub\"><li>O paciente <b>protege</b> a via aérea? (Glasgow ≤ 8, sem reflexo de tosse, secreção que não consegue eliminar)</li><li><b>Oxigena</b>? (SpO2 baixa apesar de O2 e VNI)</li><li><b>Ventila</b>? (CO2 subindo, acidose, fadiga)</li><li>Qual o <b>curso esperado</b>? (queimadura de via aérea, angioedema progressivo, transporte longo de paciente grave)</li></ul>", "Antecipar a via aérea difícil: <b>LEMON</b> (olhar, avaliar 3-3-2, Mallampati, obstrução, mobilidade do pescoço) e fisiologia difícil (hipotensão, hipoxemia, acidose grave)."]}, {"t": "lance", "q": "Quais as quatro perguntas para indicar intubação?", "a": "Protege a via aérea? Oxigena? Ventila? Qual o curso esperado?"}, {"t": "h2", "v": "Sequência rápida de intubação: os 7 P"}, {"t": "table", "head": ["P", "O quê", "Detalhes"], "rows": [["1 · Preparação", "Material e equipe", "Aspirador, O2, bolsa-válvula-máscara, laringoscópio (de vídeo se houver), tubos (7,0 a 8,0 no adulto), bougie, dispositivo supraglótico, capnógrafo, drogas aspiradas e plano B dito em voz alta"], ["2 · Pré-oxigenação", "3 min com FiO2 alta", "Máscara com reservatório, ou <b>VNI</b> (reduziu hipoxemia no PREOXI); manter cateter nasal durante a laringoscopia"], ["3 · Pré-otimização", "Corrigir antes de induzir", "Volume ou vasopressor se hipotenso (o choque pós-intubação é comum)"], ["4 · Paralisia com indução", "Indutor + bloqueador juntos", "Ver tabela de drogas"], ["5 · Posicionamento", "Orelha alinhada ao esterno", "Cabeceira elevada, coxim"], ["6 · Passagem e confirmação", "Ver o tubo passar pelas cordas", "<b>Capnografia com curva</b> é obrigatória; ausculta e expansão ajudam"], ["7 · Pós-intubação", "Sedação, analgesia e ventilador", "Fixar, RX de tórax, gasometria"]]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1056/NEJMoa2313680\" target=\"_blank\" rel=\"noopener\">Gibbs 2024 · PREOXI, N Engl J Med (PubMed) ↗</a>"}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1056/NEJMoa2301601\" target=\"_blank\" rel=\"noopener\">Prekker 2023 · DEVICE, videolaringoscópio, N Engl J Med (PubMed) ↗</a>"}, {"t": "table", "head": ["Droga", "Dose IV", "Quando escolher / cuidado"], "rows": [["Etomidato", "0,3 mg/kg", "Estável hemodinamicamente; pouca hipotensão"], ["Cetamina", "1 a 2 mg/kg", "Choque, broncoespasmo; boa na asma"], ["Propofol", "1 a 2 mg/kg", "Causa hipotensão; evitar no choque"], ["Fentanil (adjuvante)", "1 a 3 mcg/kg", "Atenua resposta simpática; cuidado na hipotensão"], ["Succinilcolina", "1 a 1,5 mg/kg", "Início rápido; <b>contraindicada</b> em hipercalemia, queimado ou esmagado após 24 a 72 h, doença neuromuscular, história de hipertermia maligna"], ["Rocurônio", "1,2 mg/kg", "Alternativa sem essas contraindicações; reversível com sugamadex 16 mg/kg"]]}, {"t": "escreva", "id": "urg-via-aerea-w-sequencia-rapida", "label": "Sequência rápida", "v": "Drogas e doses.", "li": ["Etomidato 0,3 mg/kg ou cetamina 1 a 2 mg/kg", "Succinilcolina 1,5 mg/kg ou rocurônio 1,2 mg/kg", "Confirmar com capnografia"]}, {"t": "lance", "q": "Como confirmar a posição do tubo?", "a": "Capnografia com curva (além de ausculta e expansão)."}, {"t": "h2", "v": "Primeiro ajuste do ventilador"}, {"t": "ul", "v": ["Modo volume controlado (assistido-controlado).", "<b>Volume corrente 6 a 8 mL/kg do peso predito</b> (calculado pela altura e sexo, não pelo peso real).", "FR 14 a 18 irpm (mais alta na acidose metabólica, para compensar), PEEP 5 cmH2O, <b>FiO2 100%</b> no início e descer até SpO2 92 a 96%.", "Checar a pressão de platô (alvo &lt; 30 cmH2O) e a gasometria em 30 min.", "Asma ou DPOC: FR mais baixa e tempo expiratório longo, para não aprisionar ar (auto-PEEP).", "Sedação e analgesia contínuas (fentanil e propofol ou midazolam), cabeceira a 30°."]}, {"t": "mcq", "src": "Treino · Intubação", "stem": "Homem de 40 anos, queimado há 5 dias (35% da superfície corporal), precisa de intubação. Qual bloqueador neuromuscular evitar?", "opts": ["Succinilcolina", "Rocurônio", "Ambos podem ser usados sem restrição", "Nenhum; intubar sem bloqueador"], "ok": 0, "exp": "<b>A é a correta</b>: após 24 a 72 h de queimadura extensa, há proliferação de receptores de acetilcolina extrajuncionais, e a succinilcolina pode causar hipercalemia grave e PCR. B (rocurônio 1,2 mg/kg) é a alternativa segura. C ignora essa contraindicação clássica. D: intubar sem bloqueador reduz a taxa de sucesso na primeira tentativa e aumenta complicações. <b>Revisar</b>: contraindicações da succinilcolina."}, {"t": "lance", "q": "Qual o volume corrente inicial e por qual peso?", "a": "6 a 8 mL/kg do peso predito pela altura e sexo."}]}, {"id": "urg-trauma", "title": "Trauma: atendimento inicial", "sub": "Pelo ATLS (10ª edição) e CRASH-2", "blocks": [{"t": "box", "label": "Ainda sem slides", "v": "Material de apoio pelo ATLS e por ensaios clínicos (botões abaixo). Quando os slides chegarem, eles viram a base."}, {"t": "h2", "v": "Avaliação primária: XABCDE"}, {"t": "ul", "v": ["<b>X</b> · hemorragia exsanguinante externa: compressão direta e <b>torniquete</b> em membro antes de tudo (o pré-hospitalar, pelo PHTLS, já usa o X na frente).", "<b>A</b> · via aérea <b>com restrição de movimento da coluna cervical</b> (colar e alinhamento). Paciente que fala com voz normal tem via aérea pérvia no momento.", "<b>B</b> · ventilação: expor o tórax, inspecionar, auscultar, palpar. Procurar as lesões que matam já (próxima página).", "<b>C</b> · circulação e controle de hemorragia: pulso, pele, enchimento, PA; <b>dois acessos calibrosos</b>, colher tipagem; procurar sangue em <b>tórax, abdome, pelve, ossos longos e chão</b> (o \"sangue no chão e mais quatro\").", "<b>D</b> · neurológico: <b>Glasgow</b>, pupilas, sinais de lateralização.", "<b>E</b> · exposição e <b>prevenção de hipotermia</b> (manta, fluidos aquecidos).", "Medidas adjuntas: monitor, sonda (cuidado com uretrorragia), gasometria, <b>FAST</b> (ultrassom: pericárdio, hepatorrenal, esplenorrenal, pelve), RX de tórax e de pelve."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1016/j.anclin.2018.09.009\" target=\"_blank\" rel=\"noopener\">Galvagno 2019 · ATLS 10ª edição, Anesthesiol Clin (PubMed) ↗</a>"}, {"t": "escreva", "id": "urg-trauma-w-xabcde", "label": "XABCDE", "v": "Uma linha por letra.", "li": ["X: torniquete e compressão", "A: via aérea + colar", "B: tórax (pneumotórax, hemotórax)", "C: 2 acessos, achar o sangue", "D: Glasgow e pupilas; E: despir e aquecer"]}, {"t": "lance", "q": "Onde procurar sangue no paciente traumatizado em choque?", "a": "No chão (externo), tórax, abdome, pelve e ossos longos."}, {"t": "h2", "v": "As lesões do B que matam em minutos"}, {"t": "table", "head": ["Lesão", "Clínica", "Conduta imediata"], "rows": [["Pneumotórax hipertensivo", "Dispneia, hipotensão, MV abolido, hipertimpanismo, desvio de traqueia, turgência jugular", "<b>Diagnóstico clínico</b>: descompressão por agulha no <b>4º ou 5º espaço intercostal, à frente da linha axilar média</b> (adulto), depois drenagem torácica"], ["Pneumotórax aberto", "Ferida aspirativa no tórax", "Curativo de três pontas, depois dreno"], ["Hemotórax maciço", "&gt; 1.500 mL na drenagem ou &gt; 200 mL/h por 2 a 4 h, choque", "Drenagem, reposição de sangue, toracotomia"], ["Tamponamento cardíaco", "Tríade de Beck: hipotensão, abafamento de bulhas, turgência jugular", "FAST, pericardiocentese ou toracotomia"], ["Tórax instável", "Movimento paradoxal de segmento costal, contusão pulmonar", "O2, analgesia, ventilação se preciso"]]}, {"t": "box", "label": "Não espere o RX", "v": "Pneumotórax hipertensivo com choque é diagnóstico à beira-leito; pedir RX antes de descomprimir é o erro clássico."}, {"t": "lance", "q": "Onde se faz a descompressão por agulha no adulto pelo ATLS 10ª edição?", "a": "No 4º ou 5º espaço intercostal, à frente da linha axilar média."}, {"t": "h2", "v": "Choque hemorrágico"}, {"t": "table", "head": ["", "Classe I", "Classe II", "Classe III", "Classe IV"], "rows": [["Perda de sangue", "&lt; 15%", "15 a 30%", "31 a 40%", "&gt; 40%"], ["FC", "Normal", "Normal ou ↑", "↑", "↑↑"], ["PA", "Normal", "Normal", "Normal ou ↓", "↓"], ["Pressão de pulso", "Normal", "↓", "↓", "↓"], ["Diurese", "Normal", "Normal", "↓", "↓↓"], ["Consciência", "Normal", "Ansioso", "Confuso", "Letárgico"], ["Sangue", "Monitorar", "Talvez", "Sim", "Protocolo de transfusão maciça"]]}, {"t": "ul", "v": ["Trauma com choque: <b>até 1 L de cristaloide</b> aquecido no adulto e passar logo para <b>sangue</b> (concentrado de hemácias, plasma e plaquetas em proporção próxima de 1:1:1).", "<b>Hipotensão permissiva</b> (PAS em torno de 80 a 90 mmHg) até o controle do sangramento, <b>exceto no TCE</b> (aí manter PAS ≥ 100 a 110).", "<b>Ácido tranexâmico 1 g IV em 10 min nas primeiras 3 h</b> do trauma, depois 1 g em 8 h: reduziu morte por sangramento no CRASH-2. Depois de 3 h, não dar.", "Tríade letal: <b>hipotermia, acidose e coagulopatia</b>. Aquecer tudo."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1016/S0140-6736(10)60835-5\" target=\"_blank\" rel=\"noopener\">CRASH-2 2010 · Ácido tranexâmico no trauma, Lancet (PubMed) ↗</a>"}, {"t": "escreva", "id": "urg-trauma-w-choque-no-trauma", "label": "Choque no trauma", "v": "O que fazer.", "li": ["Até 1 L de cristaloide, depois sangue 1:1:1", "Hipotensão permissiva, exceto no TCE", "Ácido tranexâmico 1 g em até 3 h"]}, {"t": "lance", "q": "Até quando dar ácido tranexâmico no trauma?", "a": "Nas primeiras 3 horas: 1 g em 10 min e 1 g em 8 h."}, {"t": "h2", "v": "Glasgow e o TCE"}, {"t": "table", "head": ["Abertura ocular", "Resposta verbal", "Resposta motora"], "rows": [["4 · Espontânea", "5 · Orientada", "6 · Obedece a comandos"], ["3 · Ao som", "4 · Confusa", "5 · Localiza a dor"], ["2 · À pressão", "3 · Palavras", "4 · Flexão normal (retirada)"], ["1 · Nenhuma", "2 · Sons", "3 · Flexão anormal (decorticação)"], ["", "1 · Nenhuma", "2 · Extensão (descerebração)"], ["", "", "1 · Nenhuma"]]}, {"t": "ul", "v": ["Somar as três respostas (3 a 15). Depois, <b>subtrair a reatividade pupilar</b> (Glasgow-P): uma pupila sem reação tira 1 ponto; as duas, 2.", "TCE leve 13 a 15; moderado 9 a 12; grave 3 a 8. <b>Glasgow ≤ 8 = intubar</b>.", "No TCE grave, evitar <b>hipotensão e hipóxia</b>: um único episódio de PAS &lt; 90 ou SpO2 &lt; 90% aumenta a mortalidade.", "Sinais de herniação (anisocoria, postura anormal, queda do Glasgow ≥ 2): cabeceira a 30°, hiperventilação breve como ponte, salina hipertônica ou manitol e neurocirurgia."]}, {"t": "escreva", "id": "urg-trauma-w-glasgow", "label": "Glasgow", "v": "Os três máximos e o corte.", "li": ["Ocular 4, verbal 5, motor 6", "Grave ≤ 8 → intubar", "Glasgow-P: tirar 1 ponto por pupila sem reação"]}, {"t": "mcq", "src": "Treino · Trauma", "stem": "Motociclista, PA 70/40, FC 140, MV abolido à direita, hipertimpanismo e turgência jugular. Primeira conduta?", "opts": ["RX de tórax para confirmar", "FAST e tomografia de tórax", "Descompressão por agulha no 4º ou 5º espaço intercostal à frente da linha axilar média", "Pericardiocentese"], "ok": 2, "exp": "<b>C é a correta</b>: é pneumotórax hipertensivo, diagnóstico clínico que pede descompressão imediata (depois, dreno). A e B atrasam um tratamento que leva segundos e o paciente pode parar enquanto isso. D trataria tamponamento, que também dá turgência e hipotensão, mas não explica MV abolido com hipertimpanismo. <b>Revisar</b>: lesões do B e local da descompressão no ATLS 10ª edição."}, {"t": "lance", "q": "Qual Glasgow indica intubação?", "a": "8 ou menos."}]}, {"id": "urg-metabolico", "title": "Emergências metabólicas", "sub": "Cetoacidose, estado hiperosmolar, hipoglicemia e hipercalemia", "blocks": [{"t": "box", "label": "Ainda sem slides", "v": "Material de apoio pelo consenso ADA/EASD de 2024 para crises hiperglicêmicas e pela conferência KDIGO sobre potássio (botões abaixo). Quando os slides chegarem, eles viram a base."}, {"t": "h2", "v": "Cetoacidose diabética: diagnóstico"}, {"t": "p", "v": "Pelo consenso de 2024, o diagnóstico precisa das três letras, <b>D, K e A</b>:"}, {"t": "table", "head": ["", "Critério"], "rows": [["D · Diabetes/hiperglicemia", "Glicemia ≥ 200 mg/dL <b>ou</b> diabetes conhecido (a cetoacidose euglicêmica com iSGLT2 entra aqui)"], ["K · Cetose", "β-hidroxibutirato ≥ 3,0 mmol/L ou cetonúria ≥ 2+"], ["A · Acidose", "pH &lt; 7,3 e/ou bicarbonato &lt; 18 mmol/L"]]}, {"t": "ul", "v": ["Calcular o <b>ânion gap</b> = Na − (Cl + HCO3); normal 8 a 12. Na CAD está aumentado.", "Procurar o gatilho: <b>infecção</b>, suspensão da insulina, IAM, AVC, pancreatite, gestação, drogas (corticoide, iSGLT2).", "<b>Estado hiperglicêmico hiperosmolar (EHH)</b>: glicemia ≥ 600 mg/dL, osmolalidade efetiva &gt; 300 mOsm/kg, sem cetose importante e sem acidose (pH ≥ 7,3, bicarbonato ≥ 15). Mais em idosos, desidratação maior, mais rebaixamento."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.2337/dci24-0032\" target=\"_blank\" rel=\"noopener\">Umpierrez 2024 · Consenso de crises hiperglicêmicas, Diabetes Care (PubMed) ↗</a>"}, {"t": "lance", "q": "Quais os três critérios (D, K, A) da CAD no consenso 2024?", "a": "Glicemia ≥ 200 ou DM conhecido; β-hidroxibutirato ≥ 3,0 mmol/L; pH &lt; 7,3 e/ou HCO3 &lt; 18."}, {"t": "h2", "v": "Cetoacidose: tratamento em quatro frentes"}, {"t": "ul", "v": ["<b>1. Volume</b>: cristaloide (balanceado ou SF 0,9%) <b>500 a 1.000 mL/h nas primeiras 2 a 4 h</b>, depois ajustar ao estado volêmico e ao sódio corrigido.", "<b>2. Potássio antes da insulina</b>:<ul class=\"sub\"><li>K &lt; 3,5 mEq/L: <b>não começar a insulina</b>; repor potássio primeiro;</li><li>K entre 3,5 e 5,0: repor junto com a insulina para manter entre 4 e 5;</li><li>K &gt; 5,0: sem reposição, dosar a cada 2 h.</li></ul>", "<b>3. Insulina regular IV contínua 0,1 U/kg/h</b> (com ou sem bolus de 0,1 U/kg). Quando a glicemia cair abaixo de <b>250 mg/dL</b>, acrescentar <b>soro glicosado</b> (5 a 10%) e reduzir para cerca de 0,05 U/kg/h, para seguir tratando a cetose sem hipoglicemia. CAD leve a moderada: análogo de insulina rápida SC é aceitável.", "<b>4. Bicarbonato</b> só se <b>pH &lt; 7,0</b>.", "Resolução: β-hidroxibutirato &lt; 0,6 mmol/L e pH ≥ 7,3 ou bicarbonato ≥ 18. Começar a <b>insulina basal SC 1 a 2 h antes</b> de desligar a bomba."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.2337/dci24-0032\" target=\"_blank\" rel=\"noopener\">Umpierrez 2024 · Diabetes Care (PubMed) ↗</a>"}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.3949/ccjm.92a.24089\" target=\"_blank\" rel=\"noopener\">Rodriguez Alvarez 2025 · Resumo do consenso 2024, Cleve Clin J Med (PubMed) ↗</a>"}, {"t": "escreva", "id": "urg-metabolico-w-cetoacidose", "label": "Cetoacidose", "v": "Ordem do tratamento.", "li": ["Volume: 500 a 1.000 mL/h nas primeiras horas", "K &lt; 3,5: repor antes da insulina", "Insulina 0,1 U/kg/h; glicemia &lt; 250 → soro glicosado", "Bicarbonato só se pH &lt; 7,0"]}, {"t": "lance", "q": "Quando acrescentar soro glicosado na CAD?", "a": "Quando a glicemia cair abaixo de 250 mg/dL."}, {"t": "h2", "v": "Hipoglicemia"}, {"t": "ul", "v": ["Glicemia <b>&lt; 70 mg/dL</b>; grave quando há rebaixamento e o paciente precisa de ajuda.", "Consciente e deglute: 15 a 20 g de carboidrato de absorção rápida, repetir a glicemia em 15 min.", "Sem via oral: <b>glicose 50% 40 a 60 mL IV</b> (20 a 30 g) ou <b>glucagon 1 mg IM</b> se não houver acesso.", "Etilista ou desnutrido: <b>tiamina 100 mg IV antes</b> (ou junto) da glicose, para não precipitar encefalopatia de Wernicke.", "Hipoglicemia por sulfonilureia ou insulina de longa ação volta: manter soro glicosado e observar por horas."]}, {"t": "lance", "q": "O que dar antes da glicose no etilista?", "a": "Tiamina 100 mg IV."}, {"t": "h2", "v": "Hipercalemia: o ECG manda"}, {"t": "ul", "v": ["Emergência: <b>K ≥ 6,5 mEq/L</b> ou <b>qualquer alteração no ECG</b>. Primeiro afaste pseudo-hipercalemia (amostra hemolisada).", "ECG em ordem de gravidade: <b>T apiculada</b> → PR longo e P achatada → <b>QRS alargado</b> → onda senoidal → FV/assistolia."]}, {"t": "table", "head": ["Objetivo", "Medida", "Dose usual", "Início"], "rows": [["Estabilizar a membrana", "<b>Gluconato de cálcio 10%</b>", "10 mL (1 g) IV em 2 a 5 min; repetir se o ECG não melhorar", "Minutos"], ["Levar o K para dentro da célula", "<b>Insulina regular + glicose</b>", "10 U IV + 25 g de glicose (ex.: 50 mL de glicose 50%); glicemia de 1/1 h", "15 a 30 min"], ["Levar o K para dentro da célula", "<b>Salbutamol</b> inalatório", "10 a 20 mg em nebulização", "30 min"], ["Levar o K para dentro da célula", "Bicarbonato de sódio", "Se acidose metabólica associada", "Variável"], ["Tirar o K do corpo", "Furosemida, quelantes (patirômer, ciclossilicato de zircônio, poliestirenossulfonato), <b>diálise</b>", "Diálise se refratária, renal crônico ou anúria", "Horas"]]}, {"t": "box", "label": "O cálcio não baixa o potássio", "v": "Ele só protege o coração por 30 a 60 min. Sempre emende com insulina e glicose e trate a causa."}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1016/j.kint.2019.09.018\" target=\"_blank\" rel=\"noopener\">Clase 2020 · KDIGO, potássio e discalemias, Kidney Int (PubMed) ↗</a>"}, {"t": "escreva", "id": "urg-metabolico-w-hipercalemia", "label": "Hipercalemia", "v": "As três frentes.", "li": ["Cálcio: estabiliza a membrana (não baixa K)", "Insulina 10 U + glicose, salbutamol: K para dentro", "Furosemida, quelante, diálise: K para fora"]}, {"t": "mcq", "src": "Treino · Cetoacidose", "stem": "Jovem com DM1: glicemia 480, pH 7,12, bicarbonato 9, cetonemia 5,8 mmol/L, K 3,1 mEq/L. Após iniciar o volume, qual o próximo passo?", "opts": ["Insulina regular 0,1 U/kg/h imediatamente", "Repor potássio e só iniciar a insulina quando K ≥ 3,5", "Bicarbonato de sódio, porque o pH está abaixo de 7,2", "Insulina SC e alta com orientação"], "ok": 1, "exp": "<b>B é a correta</b>: a insulina joga potássio para dentro da célula; com K &lt; 3,5 ela pode causar hipocalemia grave e arritmia. A seria correta só com K ≥ 3,5. C: bicarbonato apenas com pH &lt; 7,0. D: CAD grave exige insulina IV, monitorização e internação. <b>Revisar</b>: as faixas de potássio que decidem a insulina."}, {"t": "mcq", "src": "Treino · Hipercalemia", "stem": "Renal crônico, K 7,4 mEq/L, ECG com QRS largo. Qual a primeira medicação?", "opts": ["Gluconato de cálcio 10% IV", "Poliestirenossulfonato de cálcio VO", "Furosemida 40 mg IV", "Insulina regular 10 U + glicose"], "ok": 0, "exp": "<b>A é a correta</b>: com alteração de ECG, o primeiro passo é estabilizar a membrana do miócito com cálcio, em minutos. D vem logo em seguida, para baixar o K. B e C demoram horas para agir e não protegem o coração agora; C ainda depende de função renal. <b>Revisar</b>: ordem estabilizar, deslocar, remover."}, {"t": "lance", "q": "O cálcio baixa o potássio?", "a": "Não; só estabiliza a membrana do miócito por 30 a 60 min."}]}, {"id": "urg-intox", "title": "Intoxicações", "sub": "Toxíndromes, antídotos e as intoxicações mais vistas no PS", "blocks": [{"t": "box", "label": "Ainda sem slides", "v": "Material de apoio por consensos e revisões (botões abaixo). Quando os slides chegarem, eles viram a base. Em dúvida, ligue para o <b>Disque-Intoxicação: 0800 722 6001</b> (Anvisa, rede de centros de informação toxicológica)."}, {"t": "h2", "v": "Abordagem do intoxicado"}, {"t": "ul", "v": ["ABCDE primeiro, com <b>glicemia capilar</b> e ECG (QRS e QT).", "História: o quê, quanto, quando, por qual via, intencional ou não; trazer a caixa ou a cartela; procurar frascos.", "Reconhecer a <b>toxíndrome</b> (próxima página), que muitas vezes diz a classe antes do exame.", "Descontaminação: <b>carvão ativado 1 g/kg</b> (máx. 50 g) se a ingestão for recente (em geral até 1 a 2 h), a substância adsorver e a via aérea estiver protegida. Não adsorve: álcoois, ferro, lítio, ácidos e álcalis.", "Lavagem gástrica não é rotina.", "Sempre avaliar risco de suicídio na intoxicação intencional, antes da alta."]}, {"t": "lance", "q": "Qual a dose de carvão ativado e quando usar?", "a": "1 g/kg (máx. 50 g), ingestão recente (até 1 a 2 h), substância que adsorve e via aérea protegida."}, {"t": "h2", "v": "As toxíndromes"}, {"t": "table", "head": ["Toxíndrome", "Exemplos", "Pupila", "Pele", "Outros"], "rows": [["Anticolinérgica", "Anti-histamínicos, tricíclicos, atropina, plantas (trombeteira)", "Midríase", "Seca, quente, vermelha", "Delírio, retenção urinária, íleo, taquicardia (\"seco como um osso, vermelho como beterraba, louco como chapeleiro\")"], ["Colinérgica", "Organofosforados, carbamatos (\"chumbinho\")", "<b>Miose</b>", "Sudorese", "Salivação, lacrimejamento, broncorreia, diarreia, bradicardia, fasciculações"], ["Simpatomimética", "Cocaína, anfetaminas", "Midríase", "<b>Sudorese</b>", "Agitação, taquicardia, hipertensão, hipertermia, convulsão"], ["Opioide", "Morfina, fentanil, tramadol", "<b>Miose puntiforme</b>", "Normal", "Bradipneia, rebaixamento"], ["Sedativo-hipnótica", "Benzodiazepínicos, álcool, barbitúricos", "Normal ou miose", "Normal", "Rebaixamento com sinais vitais pouco alterados (BZD isolado)"]]}, {"t": "box", "label": "Seco ou molhado?", "v": "Midríase com pele <b>seca</b> = anticolinérgico; midríase com pele <b>suada</b> = simpatomimético. É a pergunta que separa os dois."}, {"t": "lance", "q": "Como diferenciar anticolinérgico de simpatomimético se ambos têm midríase?", "a": "Pela pele: seca no anticolinérgico, suada no simpatomimético."}, {"t": "h2", "v": "Antídotos que o plantonista precisa ter de cabeça"}, {"t": "table", "head": ["Intoxicação", "Antídoto", "Dose inicial (adulto)"], "rows": [["Opioide", "<b>Naloxona</b>", "0,04 a 0,4 mg IV, repetir/titular até FR adequada (não precisa acordar totalmente); 0,4 a 2 mg se apneia"], ["Benzodiazepínico", "Flumazenil", "Evitar de rotina: pode desencadear convulsão em usuário crônico ou com tricíclico. Prefira suporte"], ["Paracetamol", "<b>N-acetilcisteína</b>", "150 mg/kg em 1 h, 50 mg/kg em 4 h, 100 mg/kg em 16 h (esquema de 21 h)"], ["Organofosforado/carbamato", "<b>Atropina</b>", "1 a 3 mg IV, dobrando a cada 5 min até secar a secreção brônquica (FC &gt; 80, PAS &gt; 80)"], ["Tricíclico (QRS &gt; 100 ms)", "Bicarbonato de sódio", "1 a 2 mEq/kg IV em bolus"], ["Betabloqueador", "Glucagon", "3 a 5 mg IV (além de suporte)"], ["Metemoglobinemia", "Azul de metileno", "1 a 2 mg/kg IV"]]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1016/S0140-6736(07)61202-1\" target=\"_blank\" rel=\"noopener\">Eddleston 2008 · Intoxicação por organofosforado, Lancet (PubMed) ↗</a>"}, {"t": "escreva", "id": "urg-intox-w-antidotos", "label": "Antídotos", "v": "Os de cabeça.", "li": ["Opioide: naloxona, titulada pela respiração", "Paracetamol: N-acetilcisteína (150 / 50 / 100 mg/kg)", "Organofosforado: atropina até secar o pulmão", "Tricíclico com QRS largo: bicarbonato"]}, {"t": "lance", "q": "Qual o alvo da atropinização no organofosforado?", "a": "Secar a secreção brônquica (com FC &gt; 80 e PAS &gt; 80), não a pupila."}, {"t": "h2", "v": "Paracetamol: a intoxicação silenciosa"}, {"t": "ul", "v": ["Nas primeiras 24 h o paciente pode estar <b>quase assintomático</b>; a lesão hepática aparece entre 24 e 72 h.", "Dosar o nível sérico <b>a partir de 4 h</b> da ingestão e plotar no <b>nomograma de Rumack-Matthew</b>: acima da linha de tratamento, N-acetilcisteína.", "Iniciar NAC sem esperar o nível se: ingestão desconhecida, mais de 8 h desde a ingestão, ou transaminases alteradas.", "A NAC é quase 100% protetora quando começa em até 8 h."]}, {"t": "atual", "label": "Consenso de 2023", "v": "O consenso americano e canadense de 2023 definiu ingestão aguda como apresentação entre 4 e 24 h, revisou o nomograma, trocou \"ingestão maciça\" por \"ingestão de alto risco\" (com linha própria) e detalhou quando parar a NAC.", "src": [["Dart 2023 · Consenso de intoxicação por paracetamol, JAMA Netw Open (PubMed)", "https://doi.org/10.1001/jamanetworkopen.2023.27739"]]}, {"t": "mcq", "src": "Treino · Toxíndromes", "stem": "Agricultor trazido sonolento, com sudorese, sialorreia, broncorreia, miose e FC 48. Qual o tratamento principal?", "opts": ["Naloxona 0,4 mg IV", "Flumazenil 0,2 mg IV", "Atropina IV em doses dobradas até secar as secreções brônquicas", "Fisostigmina IV"], "ok": 2, "exp": "<b>C é a correta</b>: é síndrome colinérgica (organofosforado ou carbamato); a atropina bloqueia os receptores muscarínicos e o alvo é secar o pulmão, não a pupila. A: a miose engana, mas opioide não dá sudorese, sialorreia e broncorreia. B: flumazenil é para benzodiazepínico e arriscado. D: fisostigmina é inibidor da colinesterase, antídoto do quadro anticolinérgico, e pioraria tudo. <b>Revisar</b>: toxíndrome colinérgica e alvo da atropinização."}, {"t": "lance", "q": "A partir de quantas horas o nível de paracetamol vale no nomograma?", "a": "A partir de 4 horas da ingestão."}]}, {"id": "urg-prescricao", "title": "Prescrição de plantão", "sub": "Estrutura da prescrição e sintomáticos mais usados no PS", "blocks": [{"t": "box", "label": "Ainda sem slides", "v": "Modelo de apoio. Doses e padronizações <b>variam entre serviços</b>: siga sempre o protocolo da sua unidade e a orientação do preceptor. Toda prescrição de interno é conferida e assinada pelo médico responsável."}, {"t": "h2", "v": "A estrutura de uma prescrição"}, {"t": "ul", "v": ["Cabeçalho: nome completo, idade, peso, leito, data e <b>alergias</b> (sempre perguntar).", "Ordem clássica dos itens:<ul class=\"sub\"><li><b>1. Dieta</b> (zero se vai a procedimento, rebaixado ou vomitando; branda, livre, para diabético…);</li><li><b>2. Hidratação</b> (soro de manutenção ou reposição, com volume e velocidade);</li><li><b>3. Medicações</b> fixas (antibiótico, anti-hipertensivo, anticoagulante, protetor gástrico quando indicado);</li><li><b>4. Sintomáticos</b> \"se necessário\" (dor, febre, náusea), com a condição escrita;</li><li><b>5. Cuidados</b> de enfermagem (sinais vitais de x/x h, glicemia capilar, cabeceira, decúbito, controle de diurese, cuidados com acesso);</li><li><b>6. Profilaxias</b> (tromboembolismo venoso, úlcera de estresse quando indicada).</li></ul>", "Cada medicação: <b>nome, dose, via, diluição se IV, frequência</b> e, se \"se necessário\", <b>em que situação</b>."]}, {"t": "escreva", "id": "urg-prescricao-w-prescricao", "label": "Prescrição", "v": "A ordem.", "li": ["Dieta, hidratação, medicações, sintomáticos SN", "Cuidados de enfermagem, profilaxias", "Nome, dose, via, diluição, frequência, condição"]}, {"t": "lance", "q": "Qual a ordem clássica dos itens da prescrição?", "a": "Dieta, hidratação, medicações, sintomáticos, cuidados de enfermagem e profilaxias."}, {"t": "h2", "v": "Sintomáticos mais usados (adulto)"}, {"t": "table", "head": ["Para", "Medicação", "Dose usual", "Atenção"], "rows": [["Dor/febre", "Dipirona", "1 g IV ou VO até 6/6 h", "Alergia; agranulocitose (rara)"], ["Dor/febre", "Paracetamol", "500 mg a 1 g VO 6/6 h", "Máx. 4 g/dia (3 g se hepatopata ou etilista)"], ["Dor moderada", "Cetoprofeno", "100 mg IV 12/12 h", "AINE: evitar em renal, sangramento, gestante no 3º trimestre"], ["Dor moderada", "Tramadol", "50 a 100 mg IV/VO 6/6 h", "Máx. 400 mg/dia; náusea; baixa limiar convulsivo"], ["Dor intensa", "Morfina", "2 a 4 mg IV, repetir a cada 5 a 15 min até alívio", "Depressão respiratória: ter naloxona; cuidado em idoso e renal"], ["Cólica", "Escopolamina (butilbrometo)", "20 mg IV até 8/8 h", "Retenção urinária, glaucoma"], ["Náusea/vômito", "Ondansetrona", "4 a 8 mg IV 8/8 h", "Alarga QT"], ["Náusea/vômito", "Metoclopramida", "10 mg IV 8/8 h", "Reação extrapiramidal; evitar em obstrução intestinal"], ["Profilaxia de TEV", "Enoxaparina", "40 mg SC 1x/dia", "Ajustar na disfunção renal; contraindicada se sangramento"], ["Proteção gástrica", "Omeprazol", "40 mg IV ou VO 1x/dia", "Só com indicação (ex.: HDA, ventilação mecânica, coagulopatia)"]]}, {"t": "box", "label": "Analgesia por escada", "v": "Dor leve: dipirona ou paracetamol. Moderada: associe AINE ou opioide fraco. Forte: opioide forte titulado. Reavalie a dor com escala de 0 a 10 depois de cada dose."}, {"t": "lance", "q": "Qual a dose máxima diária de paracetamol?", "a": "4 g/dia (3 g se hepatopata ou etilista)."}, {"t": "h2", "v": "Soro: manutenção e reposição"}, {"t": "ul", "v": ["<b>Reposição</b> (repor o que falta: desidratação, choque, perdas): cristaloide isotônico em bolus, preferindo <b>balanceado</b> (Ringer lactato) em grandes volumes.", "<b>Manutenção</b> (paciente em jejum, sem déficit): cerca de <b>25 a 30 mL/kg/dia</b> de água, com 1 mEq/kg/dia de sódio, potássio e 50 a 100 g/dia de glicose (para evitar cetose de jejum). Use soluções isotônicas na maioria dos casos para evitar hiponatremia.", "Reavaliar todo dia se o soro ainda é necessário; soro esquecido é uma causa comum de hiponatremia e sobrecarga."]}, {"t": "box", "label": "Artigo", "v": "<a href=\"https://doi.org/10.1056/NEJMoa1711584\" target=\"_blank\" rel=\"noopener\">Semler 2018 · SMART, N Engl J Med (PubMed) ↗</a>"}, {"t": "mcq", "src": "Treino · Prescrição", "stem": "Paciente renal crônico (TFG 20 mL/min), com cólica renal intensa, sem alergias. Qual analgésico evitar?", "opts": ["Dipirona 1 g IV", "Cetoprofeno 100 mg IV", "Escopolamina 20 mg IV", "Morfina 2 mg IV titulada"], "ok": 1, "exp": "<b>B é a correta (deve ser evitada)</b>: AINEs reduzem a perfusão renal (inibem prostaglandinas vasodilatadoras da arteríola aferente) e podem precipitar piora aguda num renal crônico. A e C são seguras aqui. D pode ser usada com titulação cuidadosa (metabólitos acumulam na doença renal, por isso doses baixas e vigilância). <b>Revisar</b>: contraindicações dos AINEs."}, {"t": "lance", "q": "Qual o volume de água de manutenção por dia no adulto?", "a": "Cerca de 25 a 30 mL/kg/dia."}]}], "cards": [], "aula": []};
